import os
from flask import Flask, request, jsonify
from jslint.jslint import JSLint

app = Flask(__name__)

@app.route('/lint', methods=['POST'])
def lint():
    path = request.json['path']

    if '..' in path or '/' in path:
        return jsonify({
            'status': 'error',
            'message': 'Invalid path'
        }), 400

    try:
        with open(path) as f:
            code = f.read()

        lint = JSLint()
        lint.jslint(code)

        with open(path, 'w') as f:
            f.write(code)

        return jsonify({
            'status': 'success',
            'message': 'Linting successful!',
